export function application(platform: string, variant = "normal") {
  const style =
    "<style>body{font-family:Arial;margin:40px;max-width:650px}label{display:block;margin:14px 0}input,select,textarea,button{padding:9px;margin:4px}fieldset{margin:15px 0}h1{font-size:24px}</style>";
  const fields =
    variant === "repeated"
      ? '<fieldset data-section="employment"><legend>Work experience 1</legend><label>Company<input></label><label>Job title<input></label></fieldset><fieldset data-section="employment"><legend>Work experience 2</legend><label>Company<input></label><label>Job title<input></label></fieldset>'
      : `<label>First name<input required id="first"></label><label>Last name<input required value="Existing" id="last"></label><label>Email address<input type="email" required id="email"></label>${variant === "sensitive" ? '<label><input type="checkbox" required id="consent">I consent to the terms</label>' : ""}${variant === "upload" ? '<label>Resume<input type="file" required></label>' : ""}${variant === "unknown" ? "<label>What is your favorite color?<input required></label>" : ""}${variant === "custom" ? '<label id="country-label">Country</label><button type="button" role="combobox" aria-labelledby="country-label" aria-controls="countries" id="country">Choose</button><div role="listbox" id="countries" hidden><div role="option" tabindex="0">United States</div><div role="option">Canada</div></div>' : ""}`;
  const script = `<script>window.submitted=0;window.advances=0;document.addEventListener('click',e=>{if(e.target.id==='country')document.querySelector('#countries').hidden=false;if(e.target.getAttribute('role')==='option'){document.querySelector('#country').textContent=e.target.textContent;e.target.setAttribute('aria-selected','true');document.querySelector('#countries').hidden=true;}if(e.target.id==='next'){window.advances++;${variant === "nochange" ? "" : `document.querySelector('main').innerHTML='<label>Phone number<input id="phone" required></label><button id="submit">Submit application</button>';`}}if(e.target.id==='submit')window.submitted++;});</script>`;
  return `<!doctype html><html><head>${style}</head><body><h1>${platform} fixture</h1><main>${fields}<button id="next" type="button">Save and continue</button></main>${script}</body></html>`;
}
